var RC = window.__RC || (window.__RC = {});

RC.scene = function(id){ MSD.cls('.rc-sc', 'on', false); MSD.cls('#rc-sc-' + id, 'on', true); };

RC.strip = function(label, text, tone){
  MSD.cls('#rc-strip', 'bad', tone === 'bad');
  MSD.cls('#rc-strip', 'good', tone === 'good');
  MSD.q('#rc-strip-l').textContent = label;
  MSD.q('#rc-strip-t').textContent = text;
};

RC.phone = function(ic, n, label, tone){
  MSD.q('#rc-ph-ic').textContent = ic;
  MSD.q('#rc-ph-n').textContent = n;
  MSD.q('#rc-ph-l').textContent = label;
  ['bad','good','warn'].forEach(function(c){ MSD.cls('#rc-screen', c, tone === c); });
};

RC.ar = function(i, tone){
  ['live','bad','ok','dim'].forEach(function(c){ MSD.cls('#rc-ar-' + i, c, tone === c); });
};

RC.box = function(id, tone){
  ['live','bad','ok','dead'].forEach(function(c){ MSD.cls('#rc-' + id, c, tone === c); });
};

RC.chip = function(id, text, tone){
  var el = MSD.q('#rc-' + id + '-v');
  el.textContent = text;
  ['ok','bad','warn'].forEach(function(c){ el.classList.toggle(c, tone === c); });
};

// The slot and the cache are the same element: dashed and empty before
// the fix, solid with the Redis icon after it.
RC.redis = function(on){
  MSD.cls('#rc-redis', 'slot', !on);
  MSD.q('#rc-redis-t').textContent = on ? 'Azure Cache for Redis' : 'No cache';
  MSD.q('#rc-redis-s').textContent = on ? 'one copy, in memory, next to the API' : 'every tap goes straight through';
};

// CPU demand in vCores on a 0-40 scale. The white line is the 8 vCores it has.
RC.meter = function(v, tone, label){
  var fill = MSD.q('#rc-fill');
  fill.style.width = Math.min(100, v / 40 * 100) + '%';
  ['bad','ok','warn'].forEach(function(c){ fill.classList.toggle(c, tone === c); });
  RC.chip('db', label || (v + ' vCores'), tone);
};

// Particle lanes, in % of the scene: phone 13, API 39, cache 58, database 80.
RC.flow = function(y1, y2, opts){
  opts = opts || {};
  return MSD.stream('#rc-scene', { from:{ x:50, y:y1 }, to:{ x:50, y:y2 },
    count: opts.count || 5, duration: opts.duration || 700, spread: 40,
    gap: opts.gap || 420, silent: opts.silent });
};
RC.once = function(y1, y2, n){
  MSD.particles('#rc-scene', { from:{ x:50, y:y1 }, to:{ x:50, y:y2 }, count:n || 6, duration:700, spread:24 });
};

RC.reset = function(){
  RC.scene('world');
  RC.phone('🍛', '₹99', 'biryani deal · 12:00', '');
  [1,2,3].forEach(function(i){ RC.ar(i, ''); });
  RC.box('api', ''); RC.box('redis', ''); RC.box('db', '');
  MSD.q('#rc-api-s').textContent = '3 instances';
  RC.chip('api', '2200 taps/s', '');
  RC.redis(false);
  RC.chip('redis', '—', '');
  RC.meter(0, '', 'idle');
};

RC.reset();
RC.chip('api', '0 taps/s', '');
RC.strip('SALE', 'A push goes to 400,000 people.', '');

MSD.after(600, function(){ MSD.punch('#rc-phone', 1); MSD.sfx.ding(); });
MSD.after(1500, function(){
  RC.ar(1, 'live'); RC.box('api', 'live');
  MSD.count('#rc-api-v', 2200, 1600, { suffix:' taps/s' });
  RC.flow(13, 39, { count:6, gap:360 });
  MSD.sfx.riser(1400);
});
MSD.after(3400, function(){
  RC.strip('ONE PAGE', 'Everyone opens the same dish page.', '');
  MSD.punch('#rc-strip', 4);
});

